const rows = await sql`select r.id, r.name, r.updated_at from resources r where r.type = 'presentation' and r.updated_at > now() - interval '3 hours' and r.name not like 'Motion %' and r.name not like 'Test deck%' order by r.updated_at desc limit 10`;
for (const r of rows) {
  const st = await sql`select state from doc_states where resource_id = ${r.id}`.catch(() => []);
  let media = '?';
  if (st[0]?.state) {
    const d = new Y.Doc();
    Y.applyUpdate(d, st[0].state);
    media = JSON.stringify(readDeck(d).slides.flatMap((s, i) => s.elements.filter((e) => e.type === 'video' || e.type === 'audio').map((e) => ({ slide: i + 1, type: e.type, src: e.src, media: e.media }))));
  }
  console.log(r.updated_at.toISOString(), r.id, r.name, media);
}
await sql.end();
EOF
